INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(9501, '2 Kings 19:4', '2 Kings', 19, 4, '&nbsp;د اسور بادشاه خپل مشر آفسر د ژوندى خُدائ د بې‌عزتۍ کولو دپاره رالېږلے دے. مالِک خُدائ ستاسو خُدائ پاک دې د دې بې‌عزتۍ نه خبر شى او چې چا دا بې‌عزتى کړې وى نو هغوئ له دې سزا ورکړى. زمونږ د ژوندو پاتې خلقو دپاره خُدائ پاک ته سوال وکړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9502, '2 Kings 19:5', '2 Kings', 19, 5, '&nbsp;کله چې يشعياه ته د حزقياه بادشاه پېغام مِلاو شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9503, '2 Kings 19:6', '2 Kings', 19, 6, '&nbsp;نو يشعياه هغوئ ته وفرمائيل، ”خپل نېک ته ووايئ چې مالِک خُدائ داسې فرمائى چې، کومې خبرې تا اورېدلې دى د هغې په وجه مۀ يرېږه، چې د اسور بادشاه نوکرانو په هغې کښې زما ګستاخى کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9504, '2 Kings 19:7', '2 Kings', 19, 7, '&nbsp;غوږ ونيسه، مالِک خُدائ به په بادشاه باندې يوه افواه واوروى نو هغه به واپس خپل مُلک ته لاړ شى او مالِک خُدائ به يې هلته په چا ووژنى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9505, '2 Kings 19:8', '2 Kings', 19, 8, '&nbsp;د اسور آفسر خبر شو چې بادشاه د لکيس نه تلے دے او د نزدې ښار لِبناه خِلاف جنګ کوى، نو هغه ورَغلو چې مشوره ورسره وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9506, '2 Kings 19:9', '2 Kings', 19, 9, '&nbsp;اسوريانو له دا خبر ورورسېدو چې د ايتهوپيا بادشاه ترهاقه د مشرۍ لاندې مِصرے لښکر په هغوئ باندې د حملې دپاره راروان دے. کله چې بادشاه د دې نه خبر شو، نو هغۀ د يهوداه بادشاه حزقياه له دا پېغام ولېږلو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9507, '2 Kings 19:10', '2 Kings', 19, 10, '&nbsp;چې هغۀ ته داسې ووائى، ”په کوم خُدائ چې تاسو يقين کوئ هغۀ تاسو ته فرمائيلى دى چې تاسو به زما په قبضه کښې نۀ راځئ، خو چې په هغۀ باندې دوکه نۀ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9508, '2 Kings 19:11', '2 Kings', 19, 11, '&nbsp;ګورئ چې د اسور بادشاه د کوم مُلک تباه کولو فېصله وکړى نو په هغې باندې څۀ کوى، ستاسو خيال دے چې خلاص به شئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9509, '2 Kings 19:12', '2 Kings', 19, 12, '&nbsp;زما پلار نيکۀ د جوزان، حاران او رصف ښارونه تباه کړل، د بيت‌عدن خلق يې ووژل چې کوم په تلسار کښې اوسېدل او د هغوئ يو خُدائ هم هغوئ بچ نۀ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9510, '2 Kings 19:13', '2 Kings', 19, 13, '&nbsp;د حمات، ارفاد، سفروائم، هينع او د عِواه ښارونو بادشاهان چرته دى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9511, '2 Kings 19:14', '2 Kings', 19, 14, '&nbsp;حزقياه بادشاه د پېغام وړونکو نه خط واخستلو او وې لوستلو. بيا هغه د مالِک خُدائ کور ته لاړو او خط يې هلته د مالِک خُدائ په حضور کښې کېښودو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9512, '2 Kings 19:15', '2 Kings', 19, 15, '&nbsp;او دُعا يې وکړه، ”اے مالِکه خُدايه، د اِسرائيل خُدايه پاکه، تۀ د وزرو والا مخلوق په مينځ کښې په تخت ناست يې، يواځې تۀ خُدائ پاک يې، چې د دُنيا په ټولو بادشاهانو باندې حکومت کوې. تا زمکه او آسمان پېدا کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9513, '2 Kings 19:16', '2 Kings', 19, 16, '&nbsp;نو مالِکه خُدايه، چې په مونږ څۀ کيږى هغې ته وګوره. هغه ټولې خبرې واوره چې سينحرب يې تا يعنې ژوندى خُدائ پاک ته د بې‌عزتۍ دپاره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9514, '2 Kings 19:17', '2 Kings', 19, 17, '&nbsp;مالِکه خُدايه، دا رښتيا دى چې د اسور بادشاهانو ډېر قومونه تباه کړى دى او د هغوئ زمکې يې شاړې کړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9515, '2 Kings 19:18', '2 Kings', 19, 18, '&nbsp;او د هغوئ خُدايان يې اور ته اچولى دى او سوزولى يې دى، اسوريانو دا ځکه تباه کړے شول، چې په حقيقت کښې دا خُدايان نۀ وُو او تش د لرګو او کاڼو نه انسانانو جوړ کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9516, '2 Kings 19:19', '2 Kings', 19, 19, '&nbsp;نو زمونږ مالِکه خُدايه پاکه، مونږ د اسوريانو نه بچ کړه او اے مالِکه خُدايه، د دُنيا ټولو قومونو ته به پته ولګى چې صرف تۀ رښتونے خُدائ پاک يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9517, '2 Kings 19:20', '2 Kings', 19, 20, '&nbsp;بيا د آموص زوئ يشعياه حزقياه له دا پېغام ولېږلو، ”مالِک خُدائ د اِسرائيل خُدائ پاک فرمائى چې، ما د اسوريانو بادشاه سينحرب په حقله ستا دُعا اورېدلې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9518, '2 Kings 19:21', '2 Kings', 19, 21, '&nbsp;مالِک خُدائ په دې حقله فرمائيلى دى چې، پېغله لور صيون تا پورې خاندى او تا ته سپک ګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9519, '2 Kings 19:22', '2 Kings', 19, 22, '&nbsp;دا تۀ په چا پورې خندا کوې او د چا بې‌عزتى کوې؟ تۀ زما يعنې د اِسرائيلو مقدس خُدائ پاک بې‌عزتى کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9520, '2 Kings 19:23', '2 Kings', 19, 23, '&nbsp;تا ما له ستا پېغام وړُونکى راولېږل چې ما ته دا لافې ووهى چې تا د خپلو ټولو جنګى ګاډو سره د لبنان اوچت غرونه فتح کړى دى، هلته دې د دِيار لوړې ونې او د نختر ښې ونې راوغورزولې او چې تۀ د ځنګلو هغه ګڼو برخو ته ورسېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9521, '2 Kings 19:24', '2 Kings', 19, 24, '&nbsp;تا لافې وهلې چې تا کوهى وکنستل او په پردو مُلکونو کښې دې اوبۀ وڅښلې او ستا فوجيانو د پښو سره د نيل درياب اوچ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9522, '2 Kings 19:25', '2 Kings', 19, 25, '&nbsp;تۀ خبر نۀ يې چې ما د دې هر څۀ ډېر د مخکښې نه منصوبه جوړه کړې وه؟ او اوس مې داسې وکړل او تا له مې دا طاقت درکړو چې د پَخو دېوالونو ښارونه د خاورو په ډېرو بدل کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9523, '2 Kings 19:26', '2 Kings', 19, 26, '&nbsp;د هغه ځائ خلق کمزورى وُو، هغوئ يرېدلى او شرمېدلى وُو. هغوئ په پټى کښې د بوټو په شان وُو يا لکه چې په چت باندې واښۀ شوى وى چې د نمرخاتۀ ګرمې هوا وهلى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9524, '2 Kings 19:27', '2 Kings', 19, 27, '&nbsp;خو ما ته پته ده چې تۀ څۀ کوې او چرته ځې او چې تۀ ما ته څومره غصه يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9525, '2 Kings 19:28', '2 Kings', 19, 28, '&nbsp;ما ته ستا د غضب او غرور خبر رارسېدلے دے، نو زۀ به ستا په پوزه کښې کُنډه او ستا په خولۀ کښې واګې اچوم او چې په کومه لار راغلے يې نو په هغې به دې واپس ولېږم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9526, '2 Kings 19:29', '2 Kings', 19, 29, '&nbsp;نو يشعياه حزقياه بادشاه ته وفرمائيل، ”څۀ چې کېدونکى دى نو د هغې په حقله به درته ووايم. په دې کال او په بل کال به تۀ قدرتى شوے خوراک خورې، خو په ورپسې کال به غله وکرې او وبه يې رېبې او د انګورو باغونه به وکرې او انګور به وخورې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9527, '2 Kings 19:30', '2 Kings', 19, 30, '&nbsp;په يهوداه کښې چې کوم کسان ژوندى پاتې دى، نو هغوئ به د هغه بوټو په شان آباد شى چې جرړې يې په زمکه کښې ژورې ځى او مېوه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9528, '2 Kings 19:31', '2 Kings', 19, 31, '&nbsp;په يروشلم کښې او د صيون په غرۀ باندې به خلق ژوندى پاتې شى، ځکه چې د مالِک خُدائ ربُ الافواج غېرت به داسې وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9529, '2 Kings 19:32', '2 Kings', 19, 32, '&nbsp;مالِک خُدائ د اسور بادشاه په حقله فرمائيلى دى، هغه به دې ښار ته نۀ ننوځى او نۀ به د دې خِلاف يو غشے وولى. يو فوجى به هم د ډال سره دې ښار ته نزدې رانۀ شى او د دې محاصرې دپاره به د خاورو ډېرے جوړ نۀ کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9530, '2 Kings 19:33', '2 Kings', 19, 33, '&nbsp;هغه چې په کومه لار راغلے وى نو په هغې به واپس لاړ شى او ښار ته به دننه لاړ نۀ شى. ما، يعنې مالِک خُدائ داسې فرمائيلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9531, '2 Kings 19:34', '2 Kings', 19, 34, '&nbsp;د خپل عزت او د خپل خِدمت کوونکى داؤد د خاطره به زۀ د دې ښار ساتنه او حِفاظت کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9532, '2 Kings 19:35', '2 Kings', 19, 35, '&nbsp;په هغه شپه د اسوريانو خېمو ته د مالِک خُدائ يوه فرښته ننوتله او يو لاک پينځۀ اتيا زره فوجيان يې ووژل. په ورپسې سحر وختى هغوئ ټول هلته مړۀ پراتۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9533, '2 Kings 19:36', '2 Kings', 19, 36, '&nbsp;بيا د اسور بادشاه سينحرب راواپس شو او نينوه ته لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9534, '2 Kings 19:37', '2 Kings', 19, 37, '&nbsp;يوه ورځ چې هغۀ د خپل معبود نِسروک په عبادتخانه کښې عبادت کولو، نو د هغۀ دوو زامنو ادرمُلِک او شراضر هغه د خپلو تُورو سره ووژلو او بيا هغوئ د اراراط مُلک ته وتښتېدل. د هغۀ يو بل زوئ اسرحدون د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9535, '2 Kings 20:1', '2 Kings', 20, 1, '&nbsp;په هغه ورځو کښې حزقياه بادشاه بيمار شو او مرګ ته نزدې وو. د آموص زوئ، يشعياه پېغمبر ورَغلو او هغۀ ته يې وفرمائيل، ”مالِک خُدائ تا ته فرمائى چې خپلې معاملې سمبال کړه. ځکه چې تۀ به مړ کېږې، تۀ به روغ نۀ شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9536, '2 Kings 20:2', '2 Kings', 20, 2, '&nbsp;حزقياه مخ دېوال ته واړولو او دُعا يې وکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9537, '2 Kings 20:3', '2 Kings', 20, 3, '&nbsp;”مالِکه خُدايه، هغه راياد کړه، چې ما په ايماندارۍ او د زړۀ د اخلاصه ستا خِدمت کړے دے او ستا د رضا دپاره مې هر کار کړے دے.“ او هغۀ ډېر په چغو چغو وژړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9538, '2 Kings 20:4', '2 Kings', 20, 4, '&nbsp;يشعياه د بادشاه نه روان شو، خو هغه لا د محل د مرکزى دربار نه تېر شوے نۀ وو چې د مالِک خُدائ کلام پرې نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9539, '2 Kings 20:5', '2 Kings', 20, 5, '&nbsp;”د مالِک خُدائ د خلقو بادشاه حزقياه له واپس لاړ شه او هغۀ ته ووايه، ما يعنې مالِک خُدائ، ستا د پلار نيکۀ داؤد خُدائ پاک ستا دُعا اورېدلې ده او ستا اوښکې مې ليدلې دى. زۀ به تا روغ کړم او په درې ورځو کښې به د مالِک خُدائ کور ته لاړ شې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9540, '2 Kings 20:6', '2 Kings', 20, 6, '&nbsp;زۀ به ستا په عُمر کښې پينځلس کاله نور زيات کړم. زۀ به تا او د يروشلم دا ښار د اسور بادشاه نه بچ کړم. زۀ به د خپل عزت او د خپل خِدمت کوونکى داؤد د خاطره د دې ښار حِفاظت کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9541, '2 Kings 20:7', '2 Kings', 20, 7, '&nbsp;بيا يشعياه د بادشاه کسانو ته وفرمائيل چې د هغۀ په دانه باندې د اينځر نه جوړ شوے مرهم ولګوئ، نو هغه به روغ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9542, '2 Kings 20:8', '2 Kings', 20, 8, '&nbsp;حزقياه بادشاه تپوس وکړو، ”د دې ثبوت نښه به څۀ وى چې مالِک خُدائ به ما روغ کړى او په درېمه ورځ به د مالِک خُدائ کور ته لاړ شم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9543, '2 Kings 20:9', '2 Kings', 20, 9, '&nbsp;يشعياه ورته وفرمائيل، ”مالِک خُدائ به د دې نښه درته وښائى چې هغه به خپله وعده پوره کړى. نو ستا څنګه خوښه ده چې دا سورے لس قدمه مخکښې لاړ شى يا لس قدمه وروستو لاړ شى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9544, '2 Kings 20:10', '2 Kings', 20, 10, '&nbsp;حزقياه ورته وفرمائيل، ”دا آسان دى چې په پوړۍ باندې سورے لس قدمه مخکښې لاړ شى. دا لس قدمه وروستو بوځه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9545, '2 Kings 20:11', '2 Kings', 20, 11, '&nbsp;يشعياه مالِک خُدائ ته سوال وکړو او مالِک خُدائ د احاز په پوړۍ باندې سورے لس قدمه وروستو بوتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9546, '2 Kings 20:12', '2 Kings', 20, 12, '&nbsp;تقريباً هم په هغه وخت د بابل بادشاه د بلدان زوئ، مرودک‌بلدان خبر شو چې حزقياه بادشاه بيمار دے، نو هغۀ ورله يو خط او يوه تُحفه ولېږله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9547, '2 Kings 20:13', '2 Kings', 20, 13, '&nbsp;حزقياه پېغام وړونکو ته په خېر راغلے ووئيل او هغوئ ته يې خپل سرۀ زر، سپين زر، خپلې مصالحې او قيمتى تېل او خپل ټول فوجى سامان وښودلو. د هغۀ د ګودام په کوټو کښې يا د هغۀ د بادشاهۍ په بل ځائ کښې هم داسې څۀ نۀ وُو چې هغۀ ورته ښودلى نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9548, '2 Kings 20:14', '2 Kings', 20, 14, '&nbsp;بيا يشعياه پېغمبر حزقياه بادشاه له لاړو او تپوس يې ترې نه وکړو، ”دا سړى د کوم ځائ نه راغلى دى او هغوئ تا ته څۀ وفرمائيل؟“ حزقياه ورته ووئيل، ”هغوئ د يو لرې مُلک بابل نه راغلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9549, '2 Kings 20:15', '2 Kings', 20, 15, '&nbsp;يشعياه ترې نه تپوس وکړو، ”په محل کښې يې څۀ وليدل؟“ حزقياه بادشاه جواب ورکړو، ”هغوئ هر څۀ وليدل. زما په خزانه کښې داسې څۀ نشته چې ما ورته ښودلى نۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9550, '2 Kings 20:16', '2 Kings', 20, 16, '&nbsp;بيا يشعياه بادشاه ته وفرمائيل، ”مالِک خُدائ تعالىٰ داسې فرمائى چې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9551, '2 Kings 20:17', '2 Kings', 20, 17, '&nbsp;يو داسې وخت راروان دے چې ستا په محل کښې هر يو څيز، چې ستا پلار نيکۀ تر ننه پورې جمع کړى دى، نو هغه به بابل ته يوړلے شى. هيڅ به هم پاتې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9552, '2 Kings 20:18', '2 Kings', 20, 18, '&nbsp;ستا څۀ اولاد به بوتلے شى او د هغوئ نه به خصيان جوړ کړے شى چې د بابل بادشاه په محل کښې خِدمت کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9553, '2 Kings 20:19', '2 Kings', 20, 19, '&nbsp;نو حزقياه بادشاه د دې په مطلب پوهه شو چې د هغۀ په ژوند کښې به امن او تحفُظ وى، نو هغۀ ورته ووئيل، ”تا چې ما له د مالِک خُدائ نه کوم پېغام راوړے دے هغه ښۀ دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9554, '2 Kings 20:20', '2 Kings', 20, 20, '&nbsp;نور هر څۀ چې حزقياه بادشاه کړى وُو، د هغۀ د بهادرۍ کارنامې او هغه حِساب کِتاب چې هغۀ ډنډ جوړ کړے وو او چې يو سورنګ يې کنستلے وو چې ښار له اوبۀ راولى، دا هر څۀ د يهوداه د بادشاهانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9555, '2 Kings 20:21', '2 Kings', 20, 21, '&nbsp;حزقياه مړ شو او د هغۀ زوئ منسى د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9556, '2 Kings 21:1', '2 Kings', 21, 1, '&nbsp;منسى د دولسو کالو وو چې هغه د يهوداه بادشاه جوړ شو او هغۀ په يروشلم پينځۀ پنځوس کاله بادشاهى وکړه. د هغۀ مور حفصيباه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9557, '2 Kings 21:2', '2 Kings', 21, 2, '&nbsp;منسى د هغه قومونو پليت رِواجونه کول چې مالِک خُدائ د اِسرائيلو نه وړاندې شړلى وُو، او په دې کولو يې د مالِک خُدائ خِلاف ګناه وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9558, '2 Kings 21:3', '2 Kings', 21, 3, '&nbsp;هغۀ د غېرو قومونو د عبادت ځايونه بيا جوړ کړل کوم چې د هغۀ پلار حزقياه تباه کړى وُو، هغۀ د بعل د عبادت دپاره قربان‌ګاه جوړې کړې او د اِسرائيل بادشاه اخى‌اب په شان د اشيرې بُت نښه يې جوړه کړه. منسى د ستورو عبادت هم کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9559, '2 Kings 21:4', '2 Kings', 21, 4, '&nbsp;هغۀ د مالِک خُدائ په کور کښې د غېرو قومونو قربان‌ګاه جوړې کړې، په هغه ځائ کښې چې مالِک خُدائ فرمائيلى وُو، ”زما نوم به په يروشلم کښې همېشه باقى پاتې وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9560, '2 Kings 21:5', '2 Kings', 21, 5, '&nbsp;د مالِک خُدائ د کور په دوو دربارونو کښې هغۀ د ستورو د عبادت دپاره قربان‌ګاه جوړې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9561, '2 Kings 21:6', '2 Kings', 21, 6, '&nbsp;هغۀ خپل زوئ د سوزېدونکې نذرانې په توګه پېش کړو. هغۀ د کوډو او جادو نه کار واخستو او قسمت ښودونکو او فالګرو سره يې مشورې کولې. هغۀ د مالِک خُدائ خِلاف لويه ګناه وکړه او د هغۀ غصه يې راوپاروله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9562, '2 Kings 21:7', '2 Kings', 21, 7, '&nbsp;هغۀ د اشيرې بُت نښه د مالِک خُدائ په کور کښې کېښوده، چې د دې په حقله مالِک خُدائ داؤد او د هغۀ زوئ سليمان ته فرمائيلى وُو، ”په يروشلم کښې، په دې کور کښې هغه ځائ دے چې ما د بنى اِسرائيلو د ټولو دولسو قبيلو نه خوښ کړے دے چې چرته به زما د نوم درناوے کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9563, '2 Kings 21:8', '2 Kings', 21, 8, '&nbsp;او کۀ اِسرائيليان زما ټول حُکمونه منى او هغه ټول قانون ومنى چې زما خِدمت کوونکى موسىٰ هغوئ له ورکړے دے، نو هغوئ به د هغه مُلک نه نۀ شى شړلے چې ما د هغوئ پلار نيکۀ له ورکړے وو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9564, '2 Kings 21:9', '2 Kings', 21, 9, '&nbsp;خو د يهوداه خلقو د مالِک خُدائ تابعدارى نۀ کوله او منسى هغوئ د هغې نه هم لويو ګناهونو کولو طرف ته بوتلل چې کوم هغه قومونو کړى وُو چې مالِک خُدائ هغوئ د هغه مُلک نه شړلى وُو چې په کوم وخت کښې د هغۀ خلق مخ په وړاندې تلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9565, '2 Kings 21:10', '2 Kings', 21, 10, '&nbsp;د خپلو خِدمت کوونکو پېغمبرانو په ذريعه مالِک خُدائ فرمائيلى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9566, '2 Kings 21:11', '2 Kings', 21, 11, '&nbsp;”منسى بادشاه حرام کارونه کړى دى، د هغه کارونو نه هم ډېر بد چې کوم کنعانيانو کړى وُو، او هغۀ د خپلو بُتانو سره د يهوداه خلق د ګناه طرف ته بوتلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9567, '2 Kings 21:12', '2 Kings', 21, 12, '&nbsp;نو زۀ مالِک خُدائ د اِسرائيل خُدائ پاک په يروشلم او په يهوداه يو داسې افت راولم چې هر څوک د دې نه خبر شى نو په هغوئ به وېښتۀ زيګ‌زيګ ودريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9568, '2 Kings 21:13', '2 Kings', 21, 13, '&nbsp;زۀ به يروشلم له داسې سزا ورکړم لکه چې سامريه، د اِسرائيل بادشاه اخى‌اب او د هغۀ اولاد له مې ورکړې وه. زۀ به يروشلم د دې د خلقو نه داسې خالى کړم، لکه چې څوک لوښے صفا کړى او په بل مخ يې واړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9569, '2 Kings 21:14', '2 Kings', 21, 14, '&nbsp;چې کوم خلق ژوندى پاتې وى نو زۀ به يې پرېږدم او خپلو دشمنانو ته به يې حواله کړم، چې فتح يې کړى او د هغوئ مُلک لوټ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9570, '2 Kings 21:15', '2 Kings', 21, 15, '&nbsp;زۀ د خپلو خلقو سره داسې ځکه کوم چې هغوئ زما خِلاف ګناه کړې ده. او د هغه وخت نه چې د هغوئ پلار نيکۀ د مِصر نه راوتلى دى تر نن ورځې پورې يې زما غصه راپارولې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9571, '2 Kings 21:16', '2 Kings', 21, 16, '&nbsp;منسى دومره ډېر بې‌ګناه خلق قتل کړل چې د يروشلم د يو سر نه تر بل سر پورې وينې بهېدلې، د دې نه علاوه هغۀ د يهوداه خلق د بُت پرستۍ طرف ته بوتلل او هغوئ يې دې ته جوړ کړل چې د مالِک خُدائ خِلاف ګناه وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9572, '2 Kings 21:17', '2 Kings', 21, 17, '&nbsp;نور هر څۀ چې منسى کړى وُو، سره د هغه ګناهونو چې هغۀ کړى وُو، نو هغه د يهوداه د بادشاهانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9573, '2 Kings 21:18', '2 Kings', 21, 18, '&nbsp;منسى مړ شو او د محل په باغ يعنې د عُزا په باغ کښې ښخ شو، د هغۀ زوئ امون د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9574, '2 Kings 21:19', '2 Kings', 21, 19, '&nbsp;امون د دوويشتو کالو وو چې هغه د يهوداه بادشاه جوړ شو او دوه کاله يې په يروشلم بادشاهى وکړه. د هغۀ مور مسلمت وه چې د يُطبه د ښار د حروص لور وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9575, '2 Kings 21:20', '2 Kings', 21, 20, '&nbsp;د خپل پلار منسى په شان، هغۀ هم د مالِک خُدائ خِلاف ګناه وکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9576, '2 Kings 21:21', '2 Kings', 21, 21, '&nbsp;هغه د خپل پلار په نقش قدم باندې روان وو او چې د هغۀ پلار د کومو بُتانو خِدمت کړے وو نو هغۀ هم ورته سجدې لګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
