(9579, '2 Kings 21:24', '2 Kings', 21, 24, '&nbsp;د يهوداه خلقو د امون قاتِلان ووژل او د هغۀ زوئ يوسياه يې د هغۀ په ځائ بادشاه جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9580, '2 Kings 21:25', '2 Kings', 21, 25, '&nbsp;امون چې نور هر څۀ کړى وُو هغه د يهوداه د بادشاهانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9581, '2 Kings 21:26', '2 Kings', 21, 26, '&nbsp;امون د عُزا د باغ په اديره کښې ښخ شو او د هغۀ زوئ يوسياه د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9582, '2 Kings 22:1', '2 Kings', 22, 1, '&nbsp;يوسياه د اتو کالو وو چې هغه د يهوداه بادشاه شو او هغۀ په يروشلم باندې يو دېرش کاله بادشاهى وکړه. د هغۀ مور جديده وه، چې د بُصقت ښار د عداياه لور وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9583, '2 Kings 22:2', '2 Kings', 22, 2, '&nbsp;يوسياه هغه کار کولو چې مالِک خُدائ پرې رضا کېدو، هغۀ د خپل پلار نيکۀ داؤد په مِثالونو عمل کولو او د دې نه يو خوا بل خوا نۀ اوړېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9584, '2 Kings 22:3', '2 Kings', 22, 3, '&nbsp;د خپلې بادشاهۍ په اتلسم کال، يوسياه بادشاه د دربار منشى سافن چې د اصلياه زوئ او مسلام نمسے وو، د دې حُکم سره د مالِک خُدائ کور ته ولېږلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9585, '2 Kings 22:4', '2 Kings', 22, 4, '&nbsp;”مشر اِمام خِلقياه له لاړ شه او د هغه پېسو پته ولګوه چې د مالِک خُدائ د کور د ننوتلو په دروازه کښې خادمانو د خلقو نه راغونډې کړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9586, '2 Kings 22:7', '2 Kings', 22, 7, '&nbsp;خو چې هغوئ له کومې پېسې ورکړے شوې وى نو د هغې حِساب کِتاب ورسره مۀ کوئ، ځکه چې هغوئ د ايماندارۍ سره لېن دېن کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9587, '2 Kings 22:8', '2 Kings', 22, 8, '&nbsp;سافن منشى خِلقياه ته د بادشاه حُکم ورسولو او خِلقياه هغۀ ته ووئيل چې هغۀ د مالِک خُدائ په کور کښې د تورات کِتاب موندلے دے. خِلقياه کِتاب ورکړو او سافن ولوستلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9588, '2 Kings 22:9', '2 Kings', 22, 9, '&nbsp;بيا هغه واپس بادشاه له لاړو او د دې نه يې خبر کړو، ”د مالِک خُدائ په کور کښې چې کومې پېسې جمع شوې وې هغه ستا خِدمت کوونکو اخستې دى او هغه سړو له يې ورکړې دى چې د مرمت مشران دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9589, '2 Kings 22:10', '2 Kings', 22, 10, '&nbsp;او هغۀ ووئيل، ”ما سره دلته يو کِتاب دے چې خِلقياه راکړے دے.“ او بادشاه ته يې دا ولوستلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9590, '2 Kings 22:11', '2 Kings', 22, 11, '&nbsp;کله چې بادشاه د شريعت د کِتاب خبرې واورېدې، نو هغۀ د خفګان نه خپلې جامې وشلولې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9591, '2 Kings 22:12', '2 Kings', 22, 12, '&nbsp;او خِلقياه اِمام، د سافن زوئ اخيقام، د ميکاياه زوئ عکبور، د دربار منشى سافن او د بادشاه نوکر عساياه له يې دا حُکم ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9592, '2 Kings 22:13', '2 Kings', 22, 13, '&nbsp;”لاړ شئ او د مالِک خُدائ سره، زما او د يهوداه د ټولو خلقو دپاره د دې کِتاب د تعليماتو خبره وکړئ. مالِک خُدائ مونږ ته سخت غصه دے ځکه چې دا کِتاب کومې خبرې کوى نو زمونږ پلار نيکۀ په دې باندې عمل نۀ دے کړے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9593, '2 Kings 22:14', '2 Kings', 22, 14, '&nbsp;نو خِلقياه، اخيقام، عکبور، سافن او عساياه لاړل چې د خُلده نومې ښځې سره مشوره وکړى، هغه يوه پېغمبره وه چې د يروشلم په نوې محله کښې اوسېدله. (د هغې خاوند سلوم، د تِقوه زوئ او د خرخس نمسے، د مالِک خُدائ د کور د چُوغو مشر وو.) نو هغوئ ورته خبره وکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9594, '2 Kings 22:15', '2 Kings', 22, 15, '&nbsp;او هغې هغوئ ته ووئيل چې واپس بادشاه له لاړ شئ', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9595, '2 Kings 22:16', '2 Kings', 22, 16, '&nbsp;او د مالِک خُدائ دا پېغام هغۀ له ورکړئ، ”زۀ به يروشلم او د دې ټولو خلقو له سزا ورکړم لکه څنګه چې په هغه کِتاب کښې ليکلے شوى دى چې بادشاه ولوستلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9596, '2 Kings 22:17', '2 Kings', 22, 17, '&nbsp;هغوئ زۀ رد کړے يم او نورو خُدايانو ته يې نذرانې پېش کړې دى او چې هغوئ څۀ کړى دى د هغې په وجه يې زما غصه راپارولې ده. زما غصه د يروشلم خِلاف راپاڅېدلې ده او دا به نۀ سړيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9597, '2 Kings 22:18', '2 Kings', 22, 18, '&nbsp;او په خپله بادشاه ته، زۀ مالِک خُدائ د اِسرائيل خُدائ پاک داسې وايم، چې په کِتاب کښې څۀ ليکلى دى تا هغې ته غوږ ونيولو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9598, '2 Kings 22:19', '2 Kings', 22, 19, '&nbsp;او کله چې تا واورېدل چې ما يروشلم او د دې خلقو له د سزا ورکولو خبره کړې ده، نو توبه دې وويستله او عاجزى دې ښکاره کړه، جامې دې وشلولې او ودې ژړل. دا ښار به شاړ او ويجاړ کړم چې خلق به ورباندې لعنت وائى. خو ما ستا سوال اورېدلے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9599, '2 Kings 22:20', '2 Kings', 22, 20, '&nbsp;خو چې زۀ کومه سزا يروشلم له ورکوم هغه به ستا په ژوند کښې نۀ راځى. تۀ به په خېر سره مړ شې.“ نو هغه سړى د دې پېغام سره يوسياه بادشاه له راواپس شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9600, '2 Kings 23:1', '2 Kings', 23, 1, '&nbsp;بيا يوسياه بادشاه د يهوداه او يروشلم ټول مشران راوغوښتل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');